958					(0x1<<DACLMUTE) | (0x1<<DACRMUTE));
959			if (sunxi_codec->chip_ver != CHIP_VER_A) {
960				uint32_t reg_val;
961				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
962				if(!(reg_val & (0x1 << RDEN)))
963					snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
964							0x1<<RDEN, 0x1<<RDEN);
965				/* 切歌无声修复（2026-08-08）：首播（有声）采样率切换重建后
966				 * RAMP=0x40180001（bit30 置位），切歌（无声）dapm on 始终
967				 * RAMP=0x180001（bit30 未置）——bit30 是首播/切歌唯一寄存器
968				 * 差异，疑似 RAMP 偏置建立使能/完成标志。每次 open 显式置位
