974					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
975					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN));
976			if (spk) {
977				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
978				hal_gpio_set_data(param->gpio_spk, param->pa_level);
979				hal_msleep(param->pa_msleep_time);
980			}
981		} else {
982			if (spk) {
983				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
984				hal_gpio_set_data(param->gpio_spk, !param->pa_level);
985			}
986			/* analog DAC */
987			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
988					(0x1<<DACLEN) | (0x1<<DACREN),
989					(0x0<<DACLEN) | (0x0<<DACREN));
990			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
991					(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
992					(0x0<<DACLMUTE) | (0x0<<DACRMUTE));
993			/* digital DAC enable */
994			snd_codec_update_bits(codec, SUNXI_DAC_DPC,
995					(0x1<<EN_DAC), (0x0<<EN_DAC));
996			snd_codec_update_bits(codec, SUNXI_DAC_REG,
997					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
998					(0x0<<LINEOUTL_EN) | (0x0<<LINEOUTR_EN));
999			if (sunxi_codec->chip_ver != CHIP_VER_A) {
1000				uint32_t reg_val;
1001				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
1002				/* 切歌无声修复（2026-08-08）：上游此分支条件写反——
1003				 * if(!(reg_val & RDEN)) 只在 RDEN 已为 0 时才写 0，等于永不清
1004				 * 除 RAMP 使能 → 首播 close 后 RDEN 残留 1，切歌第二次 open
1005				 * 时 RAMP 状态机认为偏置已建立而跳过逐级建立 → DAC 模拟输出
1006				 * 为 0 → 无声（与"首播有声、切歌无声、寄存器全一致"完全吻合）。
1007				 * 修正为 RDEN 置位时才清零（ON 分支首播路径保持不动）。 */
1008				if(reg_val & (0x1 << RDEN))
