1012				 * open 从 0 开始重新建立（与首播冷启动路径一致）。 */
1013				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
1014						0x1<<30, 0x0<<30);
1015			}
1016		}
