static void sunxi_codec_playback_lineout_route(struct snd_codec *codec, int spk, int onoff)
{
	struct sunxi_codec_info *sunxi_codec = codec->private_data;
	struct sunxi_codec_param *param = &sunxi_codec->param;
	/* 切歌无声修复（2026-08-08 -7）：模拟电源真正下电。日志铁证——
	 * POWER/BIAS 在 dapm on/off 全程一致 = 模拟电源从未断电（代码只清
	 * 了 DACLEN/EN_DAC/LINEOUT 数字使能位），切歌第二次 open 时 RAMP
	 * 状态机认为偏置已建立而跳过逐级建立（bit30 完成标志永不置位，且
	 * -6 上板证明 bit30 是硬件状态位、软件写不进）→ DAC 模拟输出 0 →
	 * 无声。close 时保存 POWER/BIAS 后全清 + 放电延时，open 时恢复，
