695	static void sunxi_codec_init(struct snd_codec *codec)
696	{
697		struct sunxi_codec_info *sunxi_codec = codec->private_data;
698		struct sunxi_codec_param *param = &sunxi_codec->param;
699		struct alg_cfg_reg_domain domain_1bdrc = {
700			.reg_base = (void *)SUNXI_CODEC_BASE_ADDR,
701			.reg_min = SUNXI_DAC_DAP_CTL,
702			.reg_max = SUNXI_DAC_DRC_HPFLGAIN,
703		};
704	
705		/* get chp version */
706		sunxi_codec->chip_ver = hal_efuse_get_chip_ver();
707	
708		/* In order to ensure that the ADC sampling is normal,
709		 * the A chip SOC needs to always open HPLDO and RMC_EN
710		 */
711		if (sunxi_codec->chip_ver == CHIP_VER_A) {
712			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
713				(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
714			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
715				(0x1<<RMCEN), (0x1<<RMCEN));
716		} else {
717			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
718				(0x1<<HPLDO_EN), (0x0<<HPLDO_EN));
719			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
720				(0x1<<RMCEN), (0x0<<RMCEN));
721		}
722	
723		/* Disable HPF(high passed filter) */
724		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
725				(1 << HPF_EN), (0x0 << HPF_EN));
726	
727		if (param->rx_sync_en) {
728			/* disabled ADCFDT */
729			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
730					(0x1 << ADCDFEN), (0x0 << ADCDFEN));
731			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
732					(0x3 << ADCFDT), (0x2 << ADCFDT));
733			/* RX_SYNC_EN */
734			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC, 1 << RX_SYNC_EN, 0 << RX_SYNC_EN);
735		} else {
736			/* Enable ADCFDT to overcome niose at the beginning */
737			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
738					(0x1 << ADCDFEN), (0x1 << ADCDFEN));
739			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
740					(0x3 << ADCFDT), (0x2 << ADCFDT));
741		}
742	
743		/* init the mic pga and vol params */
744		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
745				0x1F << LINEOUT_VOL,
746				param->lineout_vol << LINEOUT_VOL);
747		snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
748				0x7 << HP_GAIN,
749				param->hpout_vol << HP_GAIN);
750	
751		/* DAC_VOL_SEL enable */
752		snd_codec_update_bits(codec, SUNXI_DAC_VOL_CTL,
753				(0x1 << DAC_VOL_SEL), (0x1 << DAC_VOL_SEL));
754		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
755				0x3F << DVOL,
756				param->digital_vol << DVOL);
757	
758		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
759				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN),
760				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN));
761	
762		snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
763				0x1F << ADC_PGA_GAIN_CTL,
764				param->mic1gain << ADC_PGA_GAIN_CTL);
765	
766		snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
767				0x1F << ADC_PGA_GAIN_CTL,
768				param->mic2gain << ADC_PGA_GAIN_CTL);
769	
770		snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
771				0x1F << ADC_PGA_GAIN_CTL,
772				param->mic3gain << ADC_PGA_GAIN_CTL);
773	
774	#ifdef SUNXI_CODEC_DAP_ENABLE
775		if (param->dacdrc_cfg || param->dachpf_cfg) {
776			snd_codec_update_bits(codec, SUNXI_DAC_DAP_CTL,
777					(0x1 << DDAP_EN), (0x1 << DDAP_EN));
778		}
779	
780		if (param->adcdrc_cfg || param->adchpf_cfg) {
781			snd_codec_update_bits(codec, SUNXI_ADC_DAP_CTL,
782					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN),
783					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN));
784		}
785	
786		if (param->adcdrc_cfg) {
787			adcdrc_config(codec);
788			adcdrc_enable(codec, 1);
789		}
790		if (param->adchpf_cfg) {
791			adchpf_config(codec);
792			adchpf_enable(codec, 1);
793		}
794		if (param->dacdrc_cfg) {
795			dacdrc_config(codec);
796			dacdrc_enable(codec, 1);
797		}
798		if (param->dachpf_cfg) {
799			dachpf_config(codec);
800			dachpf_enable(codec, 1);
801		}
802	#endif
803	
804		sunxi_alg_cfg_domain_set(&domain_1bdrc, SUNXI_ALG_CFG_DOMAIN_1BDRC);
