854	static void sunxi_codec_playback_hp_route(struct snd_codec *codec, int spk, int onoff)
855	{
856		struct sunxi_codec_info *sunxi_codec = codec->private_data;
857		struct sunxi_codec_param *param = &sunxi_codec->param;
858	
859		if (onoff) {
860			if (sunxi_codec->chip_ver == CHIP_VER_A) {
861				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
862						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
863						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN));
864				/* ramp out enable */
865				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
866						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
867						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH));
868				/* digital DAC enable */
869				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
870						(0x1<<EN_DAC), (0x1<<EN_DAC));
871				hal_msleep(5);
872				/* analog DAC enable */
873				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
874						(0x1<<DACLEN) | (0x1<<DACREN),
875						(0x1<<DACLEN) | (0x1<<DACREN));
876				/* HEADPONEOUT */
877				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
878					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN),
879					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN));
880				/* Playback on */
881				snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
882					(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
883			} else {
884				/* digital DAC enable */
885				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
886						(0x1<<EN_DAC), (0x1<<EN_DAC));
887				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
888						(0x1<<RDEN), (0x1<<RDEN));
889			}
890			if (spk) {
891				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
892				hal_gpio_set_data(param->gpio_spk, param->pa_level);
893				hal_msleep(param->pa_msleep_time);
894			}
895		} else {
896			if (spk) {
897				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
898				hal_gpio_set_data(param->gpio_spk, !param->pa_level);
899			}
900			/* Playback off */
901			if (sunxi_codec->chip_ver == CHIP_VER_A) {
902				/* HEADPONE_EN */
903				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
904						(0x1<<HP_DRVEN), (0x0<<HP_DRVEN));
905				/* power off */
906				/* note: HPLDO is always open to avoid KEY_ADC sampling fail */
907				/* snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL, */
908				/* 		(0x1<<HPLDO_EN), (0x0<<HPLDO_EN)); */
909				hal_msleep(30);
910				/* HEADPONE_OUT */
911				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
912						(0x1<<HP_DRVOUTEN), (0x0<<HP_DRVOUTEN));
913				/* analog DAC */
914				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
915						(0x1<<DACLEN) | (0x1<<DACREN),
916						(0x0<<DACLEN) | (0x0<<DACREN));
917				/* digital DAC */
918				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
919						(0x1<<EN_DAC), (0x0<<EN_DAC));
920	
921				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
922						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
923						(0x0<<RAMP_OUT_EN) | (0x0<<RSWITCH));
924	
925				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
926						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
927						(0x0<<HPFB_BUF_EN) | (0x0<<HPFB_IN_EN));
928			} else {
929				/* analog DAC */
930				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
931						(0x1<<DACLEN) | (0x1<<DACREN),
932						(0x0<<DACLEN) | (0x0<<DACREN));
933				/* digital DAC enable */
934				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
935						(0x1<<EN_DAC), (0x0<<EN_DAC));
936				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
937						(0x1<<RDEN), (0x0<<RDEN));
938			}
939		}
