/*
 * music_service.h — 系统级常驻音乐服务抽象层（2026-08-08）
 *
 * 架构：Music Service 是唯一持有 XPlayer/dm_sound 的模块，负责
 *   - XPlayer 生命周期（create/destroy/recreate）
 *   - 播放状态机（playing / paused / stopped）
 *   - 当前歌曲信息、播放进度
 *   - 播放控制（play/pause/resume/next/prev/volume）
 * UI（Music Page / Home Widget / Standby Widget）只读状态 + 发命令，
 * 不直接操作 XPlayer。系统级 timer 调 music_service_poll() 驱动
 * 状态机与进度更新，不绑定任何 UI 页面生命周期。
 *
 * 迁移自 deskmate_ui.c（2026-08-08）：g_xplayer/g_music_sound/
 * g_xp_state/dm_tracks/music_* 等播放核心全部收拢到此模块。
 * 保留已验证的切歌无声修复（XPlayer destroy&recreate + Ramp FSM
 * 复位）与音量衰减/dm_sound 诊断逻辑，不做音频底层改动。
 */
#ifndef __MUSIC_SERVICE_H
#define __MUSIC_SERVICE_H

#include <stdint.h>
#include <stdbool.h>

#define MUSIC_MAX_TRACKS    64
#define MUSIC_PATH_LEN      256
#define MUSIC_TITLE_LEN     128

typedef enum
{
    MUSIC_STATE_STOPPED = 0,   /* 未加载/已停止 */
    MUSIC_STATE_PLAYING,       /* 播放中 */
    MUSIC_STATE_PAUSED,        /* 暂停（已加载源） */
} music_state_t;

typedef struct
{
    char     path[MUSIC_PATH_LEN];   /* 完整文件路径 */
    char     title[MUSIC_TITLE_LEN]; /* 无扩展名文件名 */
    uint32_t length;                 /* 秒；0=未知 */
} music_track_t;

