/* ================================================================
 * XPlayer 生命周期 — 切歌走 destroy&recreate（已验证有声路径）
 * ================================================================ */

static void music_audio_start(const char *path)
{
    printf("[music] xplayer play: %s\n", path ? path : "(null)");

    if (s_xplayer != NULL)
    {
        /* 切歌无声根因修复（2026-08-07 ok-20260807-17）：XPlayerReset
         * 复用路径切歌后无声，改用 XPlayerDestroy 后重新走 create 路径。 */
        printf("[music] destroy & recreate player for new source\n");
        XPlayerDestroy(s_xplayer);
        s_xplayer = NULL;
        /* XPlayerDestroy → PlayerClear 内部已 SoundDeviceDestroy(pAudioSink)
         * 销毁 sink——此处只置 NULL，内存由 XPlayer 内部释放（二次 destroy
         * 是 double free，2026-08-08 -4 修复）。 */
        s_sound = NULL;
    }

    if (s_xplayer == NULL)
    {
        s_xplayer = XPlayerCreate();
        if (s_xplayer == NULL)
        {
            printf("[music] ERROR: XPlayerCreate() failed\n");
            return;
        }
        XPlayerSetNotifyCallback(s_xplayer, dm_xplayer_cb, NULL);
        XPlayerInitCheck(s_xplayer);
        s_sound = dm_sound_create();
        XPlayerSetAudioSink(s_xplayer, (void *)s_sound);
        printf("[music] xplayer created\n");
    }

    s_xp_state = 0;
    if (XPlayerSetDataSourceUrl(s_xplayer, path, NULL, NULL) != 0)
    {
        printf("[music] setDataSourceUrl failed, reset player\n");
        XPlayerReset(s_xplayer);
        s_xp_state = -1;           /* poll 自动跳到下一首 */
        return;
    }
    XPlayerPrepareAsync(s_xplayer);
}

static void music_audio_pause(void)
{
    if (s_xplayer) XPlayerPause(s_xplayer);
}

static void music_audio_resume(void)
{
    if (s_xplayer) XPlayerStart(s_xplayer);
}

static void music_audio_stop(void)
{
    if (s_xplayer) XPlayerStop(s_xplayer);
}

static int music_audio_position(int *ms)
{
    if (s_xplayer) return XPlayerGetCurrentPosition(s_xplayer, ms);
    return -1;
}

static int music_audio_duration(int *ms)
{
    if (s_xplayer) return XPlayerGetDuration(s_xplayer, ms);
    return -1;
}

/* ================================================================
 * 曲库扫描 + 状态记忆
 * ================================================================ */

static uint32_t music_wav_duration(const char *path)
{
    FILE *fp;
    uint8_t hdr[44];
    uint32_t byte_rate, data_len;

    fp = fopen(path, "rb");
    if (fp == NULL) return 0;

    if (fread(hdr, 1, sizeof(hdr), fp) != sizeof(hdr))
    {
        fclose(fp);
        return 0;
    }
    fclose(fp);

    if (memcmp(hdr, "RIFF", 4) != 0 || memcmp(hdr + 8, "WAVE", 4) != 0)
        return 0;

    memcpy(&byte_rate, hdr + 28, 4);
    memcpy(&data_len, hdr + 40, 4);
    if (byte_rate == 0) return 0;

    return data_len / byte_rate;
}

static uint32_t music_scan_tracks(void)
{
    static const char *supported[] = { "mp3", "wav", "flac", "ogg", "aac", NULL };
    const char *scan_dirs[] = { MUSIC_DIR, MUSIC_DIR_NORFLASH };
    uint32_t count = 0;
    int d;

    for (d = 0; d < 2; d++)
    {
        DIR *dir = opendir(scan_dirs[d]);
        struct dirent *ent;
        if (!dir)
            continue;

        while ((ent = readdir(dir)) != NULL && count < MUSIC_MAX_TRACKS)
        {
            const char *dot = strrchr(ent->d_name, '.');
            int ok = 0, i;
            if (!dot || dot == ent->d_name)
                continue;
            for (i = 0; supported[i]; i++)
            {
                if (strcasecmp(dot + 1, supported[i]) == 0)
                {
                    ok = 1;
                    break;
                }
            }
            if (!ok)
                continue;

            snprintf(s_tracks[count].path, sizeof(s_tracks[count].path),
                     "%s/%s", scan_dirs[d], ent->d_name);
            snprintf(s_tracks[count].title, sizeof(s_tracks[count].title),
                     "%.*s", (int)(dot - ent->d_name), ent->d_name);
            s_tracks[count].length = music_wav_duration(s_tracks[count].path);
            count++;
        }
        closedir(dir);
    }

    s_track_count = count;
    return count;
}

static void music_state_save(uint32_t id)
{
    FILE *f = fopen(MUSIC_STATE_FILE, "w");
    if (f)
    {
        fprintf(f, "%u\n", (unsigned)id);
        fclose(f);
    }
}

static uint32_t music_state_load(void)
{
    FILE *f = fopen(MUSIC_STATE_FILE, "r");
    uint32_t id = 0;
    if (f)
    {
        if (fscanf(f, "%u", &id) != 1)
            id = 0;
        fclose(f);
    }
    return id;
}

/* ================================================================
 * Music Service 公共 API
 * ================================================================ */

void music_service_init(void)
{
    s_track_id = 0;
    s_playing = false;
    s_inited = false;
    s_xp_state = 0;
    s_xplayer = NULL;
    s_sound = NULL;

    music_scan_tracks();
    if (s_track_count > 0)
    {
        uint32_t saved = music_state_load();
        if (saved < s_track_count)
            s_track_id = saved;
    }
    printf("[music] service init: %u tracks\n", s_track_count);
}

void music_service_poll(void)
{
    if (s_xplayer == NULL) return;

    if (s_xp_state == 1)          /* PREPARED → start playback */
    {
        s_xp_state = 2;
        XPlayerStart(s_xplayer);
        s_playing = true;
    }
    else if (s_xp_state == 3)     /* PLAYBACK_COMPLETE → auto next */
    {
        s_xp_state = 0;
        printf("[music] playback complete, next\n");
        music_service_next(true);
    }
    else if (s_xp_state == -1)    /* ERROR → skip to next */
    {
        s_xp_state = 0;
        printf("[music] xplayer error, skip\n");
        music_service_next(true);
    }
}

void music_service_play(uint32_t id)
{
    if (id >= s_track_count)
        return;
    s_track_id = id;
    s_inited = true;
    s_playing = true;
    music_state_save(id);
    music_audio_start(s_tracks[id].path);
}

void music_service_pause(void)
{
    if (!s_playing) return;
    s_playing = false;
    music_audio_pause();
}

void music_service_resume(void)
{
    if (!s_inited) return;
    if (s_playing) return;
    s_playing = true;
    music_audio_resume();
}

void music_service_toggle(void)
{
    if (s_playing)
        music_service_pause();
    else if (s_inited)
        music_service_resume();
    else
        music_service_play(s_track_id);
}

void music_service_next(bool next)
{
    if (s_track_count == 0) return;
    if (next)
        s_track_id = (s_track_id + 1) % s_track_count;
    else
        s_track_id = (s_track_id == 0) ? s_track_count - 1 : s_track_id - 1;
    s_inited = true;
    s_playing = true;
    music_state_save(s_track_id);
    music_audio_start(s_tracks[s_track_id].path);
}

void music_service_set_volume(int v)
{
    if (v < 0) v = 0;
    if (v > 100) v = 100;
    s_volume = v;
}

/* ── 状态查询 ── */

uint32_t music_service_track_count(void)
{
    return s_track_count;
}

const music_track_t *music_service_track(uint32_t id)
{
    if (id >= s_track_count)
        return NULL;
    return &s_tracks[id];
}

uint32_t music_service_current_id(void)
{
    return s_track_id;
}

const char *music_service_current_title(void)
{
    if (s_track_id < s_track_count)
        return s_tracks[s_track_id].title;
    return "";
}

music_state_t music_service_state(void)
{
    if (!s_inited)
        return MUSIC_STATE_STOPPED;
    return s_playing ? MUSIC_STATE_PLAYING : MUSIC_STATE_PAUSED;
}

bool music_service_inited(void)
{
    return s_inited;
}

int music_service_volume(void)
{
    return s_volume;
}

int music_service_position_ms(void)
{
    int ms = -1;
    music_audio_position(&ms);
    return ms;
}

int music_service_duration_ms(void)
{
    int ms = -1;
    music_audio_duration(&ms);
    return ms;
}

void music_service_get_status(music_status_t *out)
{
    if (!out) return;
    out->state       = music_service_state();
    out->track_id    = s_track_id;
    out->track_count = s_track_count;
    out->inited      = s_inited;
    out->volume      = s_volume;
    out->position_ms = music_service_position_ms();
    out->duration_ms = music_service_duration_ms();
}

